STORY = [('chun_yuqiao', '现在广告商那边已经同意改版了，邓主任是不是可以推动台里通过改版呢？', 'Now that the advertisers have agreed to the revamp, can you help push approval through at the network?', [(597, '现在广告商那边'), (598, '已经同意改版了'), (601, '推动台里通过改版呢')], ''), ('chun_yuqiao', '邓主任有什么建议？', 'What suggestions do you have in mind?', [(611, '邓主任有什么建议')], ''), ('wen_simo', '我想知道，你们这个改版方案是谁搞的？', 'I would like to know who came up with this revamp proposal of yours.', [(646, '我想知道'), (647, '你们这个改版方案是谁搞的')], ''), ('wen_simo', '怪不得呢，我都看了，我很有意见。', 'No wonder — I read the whole thing, and I have major objections.', [(649, '怪不得呢'), (650, '我都看了'), (651, '我很有意见')], ''), ('chun_yuqiao', '有什么想法你说出来吧，在我们星天一向欢迎争论的。', 'Speak your mind freely; here at Xingtian we have always welcomed debate.', [(655, '有什么想法你说出来吧'), (656, '在我们星天'), (657, '一向欢迎争论的')], ''), ('wen_simo', '这点我深有体会。我在这个圈子混了二十年了，这样的改版方案我前所未见。', 'I know that firsthand. In twenty years in this industry, I have never seen a revamp proposal like this.', [(658, '这点我深有体会'), (659, '我在这个圈子混了二十年了'), (661, '我前所未见')], ''), ('wen_simo', '对于一个引进节目做这种高度的本土化创新，这在中国的电视界从来没有过。', 'Taking an imported format and giving it such deep homegrown innovation has never been done in Chinese television.', [(664, '对于一个引进节目'), (665, '做这种高度的本土化创新'), (666, '这在中国的电视界'), (667, '从来没有过')], ''), ('wen_simo', '如果我们台能够率先垂范接受这个方案，不仅会提高我们的品牌价值。', 'If our network sets the example by adopting this plan, it will elevate our entire brand value.', [(668, '如果我们台'), (669, '能够率先垂范'), (670, '接受这个方案'), (671, '那不仅会提高'), (672, '我们的品牌价值')], ''), ('wen_simo', '这个改版方案最大的问题在于，这么好玩的事怎么不带我一块儿玩呢？', "So the single biggest flaw in this revamp plan is: why didn't you invite me along for something this fun?", [(680, '这个改版方案'), (681, '最大的问题在于'), (682, '这么好玩的事'), (684, '带我一块儿玩呢')], ''), ('chun_yuqiao', '闻老师，你不愧是独步江湖的段子手，我们开个讨论会你还卖关子呢。', 'Mr Wen, you truly live up to your reputation as a master storyteller — keeping us in suspense during a review meeting!', [(685, '闻老师'), (686, '你不愧是'), (687, '独步江湖的段子手'), (688, '我们开个讨论会'), (689, '你还卖关子呢')], ''), ('wen_simo', '你们星天要是不嫌弃的话，我个人愿意出任新一季十二歌王的主持人。', "If Xingtian doesn't mind, I would personally love to serve as host for the new season of Twelve Singers.", [(690, '你们星天要是不嫌弃的话'), (691, '我个人愿意'), (693, '出任新一季'), (694, '的主持人')], ''), ('chun_yuqiao', '你要重回综艺舞台？闻老师，一言为定！', "You're returning to the variety stage? Mr Wen, it's a deal!", [(695, '你要重回综艺舞台'), (704, '一言为定')], '')]
